+        assertThat(cache.jobQueueCount(), equalTo(0));
+    }
+
+    private void await(CyclicBarrier barrier) {
+        try {
+            barrier.await();
+        } catch (InterruptedException | BrokenBarrierException e) {
+            fail();
+        }
+    }
